sp_widget.client_script:
api.controller = function($location) {
  var c = this;

  // Set default tab based on URL table param, or default to 'leave'
  var urlTable = $location.search().table || '';
  if (urlTable.indexOf('od') > -1) {
    c.activeTab = 'od';
  } else if (urlTable.indexOf('grievance') > -1) {
    c.activeTab = 'grievance';
  } else {
    c.activeTab = 'leave';
  }

  c.selectedSysId = $location.search().sys_id || '';

  c.setTab = function(tab) {
    c.activeTab = tab;
  };
};

sp_widget.css:
.tabbed-request-container {
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 4px 15px rgba(0,0,0,0.05);
  border: 1px solid #e2e8f0;

  .custom-tabs {
    border-bottom: none;
    li a {
      font-weight: 600;
      color: #64748b;
      border: none;
      border-radius: 8px 8px 0 0;
      margin-right: 4px;
      &:hover { background: #f1f5f9; color: #1e293b; }
    }
    li.active a {
      background: #ffffff;
      color: #2563eb;
      border-bottom: 2px solid #2563eb;
    }
  }

  .badge-leave { background-color: #3b82f6; }
  .badge-od { background-color: #06b6d4; }
  .badge-grievance { background-color: #f59e0b; }

  .list-group-item {
    padding: 14px 18px;
    border-left: 3px solid transparent;
    transition: all 0.2s ease;

    &:hover {
      background-color: #f8fafc;
      border-left-color: #94a3b8;
    }

    &.active-item {
      background-color: #eff6ff;
      border-left-color: #2563eb;
    }
  }
}

sp_widget.script:
(function() {
    data.leaves = [];
    data.ods = [];
    data.grievances = [];

    var userEmail = gs.getUser().getEmail();
    var stuGr = new GlideRecord('x_1983287_studen_0_student_profile');
    stuGr.addQuery('email', userEmail);
    stuGr.query();

    var stuId = null;
    if (stuGr.next()) {
        stuId = stuGr.getUniqueValue();
    } else {
        // Fallback for Admin/Dev testing
        var testGr = new GlideRecord('x_1983287_studen_0_student_profile');
        testGr.query();
        if (testGr.next()) stuId = testGr.getUniqueValue();
    }

    if (!stuId) return;

    // 1. Fetch Leave Requests
    var lGr = new GlideRecord('x_1983287_studen_0_leave_request');
    lGr.addQuery('student', stuId);
    lGr.orderByDesc('sys_created_on');
    lGr.query();
    while (lGr.next()) {
        data.leaves.push({
            sys_id: lGr.getUniqueValue(),
            number: lGr.getValue('number') || lGr.getDisplayValue(),
            type: lGr.getValue('leave_type') || 'Leave',
            from_date: lGr.getValue('from_date') || '',
            status: lGr.getValue('status') || 'Submitted'
        });
    }

    // 2. Fetch OD Requests
    var oGr = new GlideRecord('x_1983287_studen_0_od_request');
    oGr.addQuery('student', stuId);
    oGr.orderByDesc('sys_created_on');
    oGr.query();
    while (oGr.next()) {
        data.ods.push({
            sys_id: oGr.getUniqueValue(),
            number: oGr.getValue('number') || oGr.getDisplayValue(),
            event: oGr.getValue('event_activity') || 'OD Event',
            org: oGr.getValue('organization') || 'College',
            from_date: oGr.getValue('from_date') || '',
            status: oGr.getValue('status') || 'Submitted'
        });
    }

    // 3. Fetch Grievances
    var gGr = new GlideRecord('x_1983287_studen_0_grievance_request');
    gGr.addQuery('student', stuId);
    gGr.orderByDesc('sys_created_on');
    gGr.query();
    while (gGr.next()) {
        data.grievances.push({
            sys_id: gGr.getUniqueValue(),
            number: gGr.getValue('number') || gGr.getDisplayValue(),
            category: gGr.getValue('category') || 'General',
            subject: gGr.getValue('subject') || '',
            status: gGr.getValue('status') || 'Open'
        });
    }
})();
